var i=`0854-naan`;var n=`world-0854`;var t=`IN`;var s=`south-asia`;var l=8;var o=105;var r={en:`Naan`,ua:`Наан`};var u={en:`Naan is a India dish made with all-purpose flour, plain yogurt, whole cow milk, instant yeast. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Наан, страва кухні країни Індія. Основні складники: пшеничне борошно універсальне, натуральний йогурт, цільне коров'яче молоко, інстантні дріжджі. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 75 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 75 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:75,i:[[`all-purpose-flour`,420,`g`],[`plain-yogurt`,110,`g`],[`whole-cow-milk`,110,`ml`],[`water`,105,`ml`],[`instant-yeast`,7,`g`],[`white-granulated-sugar`,10,`g`],[`table-salt`,6,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:15,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 12 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 12 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,65,`g`],[`garlic`,3,`clove`],[`cilantro`,12,`g`]]}];var d={slug:i,id:n,country:`IN`,region:s,servings:8,minutes:105,title:r,text:u,steps:g};export{t as country,d as default,n as id,o as minutes,s as region,l as servings,i as slug,g as steps,u as text,r as title};